bool cg_elides_copy(const IrInstruction* inst, const CgPlacement* placement) {
  if (inst->type == IR_INST_LOAD)
    return inst->result != IR_INVALID_ID &&
           placement[inst->result].slot != IR_INVALID_ID;

  if (inst->type == IR_INST_STORE) {
    IrOperand source = inst->operands.store.source;
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement these 2 optimalizations:\n1. [Image: image.png; ref=image_4164f575-faf4-436e-9f9e-08e5ddad1896]  In this case, v0 and v1 are only used in the first 3 lines, later, they are not. Instead of declaring v3 and v4, we could simply reuse them. As this would complicate control flow analysis do this as the last optimalization step\n2. [Image: image.png; ref=image_0d0b230f-4681-4898-927c-819ddac4d1c5]  In ifjcode, stack slots can be instruction arguments just as well as temporary variables. In these cases, forward the loaded stack slot as an argument (update IR so that stack slots can be operands). If this would complicate other analysis, also do this as the last step at the complete end"
    // Changes: Elide stores that copy a directly forwarded slot back to itself.
    return (source.type == IR_OP_SLOT &&
            source.value.slot == inst->operands.store.target) ||
           (source.type == IR_OP_VALUE &&
            placement[source.value.id].slot == inst->operands.store.target);
  }

  return false;
}
